import { randomUUID } from 'node:crypto';
const monotonic = () => Number(process.hrtime.bigint()) / 1e6;
const log = entry => console.log('R4B_EVENT ' + JSON.stringify(entry));
export function streamProbe(request, kind) {
  const probeId = randomUUID(), start = monotonic();
  let closed = false, timers = [], controller;
  const elapsed = () => Number((monotonic() - start).toFixed(3));
  const record = (event, extra = {}) => log({ probeId, kind, event, serverMonotonicMs: monotonic(), serverElapsedMs: elapsed(), ...extra });
  const clear = () => { for (const timer of timers) clearTimeout(timer); timers = []; };
  const stop = signal => {
    record(signal);
    if (closed) return;
    closed = true; clear();
    record('timers.cleared');
    if (signal === 'request.abort') { try { controller.error(new Error('Synthetic client disconnected')); } catch {} }
    request.signal.removeEventListener('abort', abort);
  };
  const abort = () => stop('request.abort');
  const body = new ReadableStream({
    start(c) {
      controller = c;
      const emit = seq => {
        if (closed) return;
        const frame = { probeId, seq, serverElapsedMs: elapsed() };
        c.enqueue(new TextEncoder().encode(JSON.stringify(frame) + '\n'));
        record('emit', { seq });
        if (seq === 3) { closed = true; clear(); request.signal.removeEventListener('abort', abort); c.close(); record('complete'); }
      };
      request.signal.addEventListener('abort', abort, { once: true });
      if (request.signal.aborted) { abort(); return; }
      emit(1);
      timers = [setTimeout(() => emit(2), 200), setTimeout(() => emit(3), 400)];
    },
    cancel() { stop('stream.cancel'); }
  }, { highWaterMark: 262144, size: chunk => chunk.byteLength });
  return new Response(body, { headers: { 'Content-Type': 'application/x-ndjson; charset=utf-8', 'Cache-Control': 'no-store', 'X-Accel-Buffering': 'no', 'X-Content-Type-Options': 'nosniff' } });
}

export function originProbe(request) {
  // Exact authority and rejection expressions copied from student-handlers.ts.
  const url = new URL(request.url), expected = `${url.protocol}//${request.headers.get('host') ?? url.host}`;
  const denied = request.headers.get('origin') !== expected || request.headers.get('sec-fetch-site') === 'cross-site';
  const status = denied ? 403 : 200;
  // Fixed diagnostic fields only; never enumerate request headers.
  const forwardedProto = request.headers.get('x-forwarded-proto');
  return Response.json({ scheme: url.protocol, host: request.headers.get('host'), forwardedProtoPresent: forwardedProto !== null, forwardedProto, expected, originMatch: request.headers.get('origin') === expected, status }, { status, headers: { 'Cache-Control': 'no-store' } });
}

