const evidence = '/home/yangzhen/projects/my-lms-system/docs/evidence/teaching-agent-stage-1f-r4b';
const local = 'http://127.0.0.1:43183';
const remote = 'https://kmgwak-system-product-name.taila18cd5.ts.net:9443';
