  const r = spawnSync('/usr/bin/tailscale', ['serve', 'status', '--json'], { encoding: 'utf8', timeout: 10000 });
  assert.equal(r.status, 0, 'SERVE_STATUS_FAILED');
  return JSON.parse(r.stdout);
}
function verifyAdded(now) {
  const expected = structuredClone(before);
  expected.TCP['9443'] = { HTTPS: true };
  expected.Web[hostname + ':9443'] = { Handlers: { '/': { Proxy: 'http://127.0.0.1:43183' } } };
  assert.deepEqual(now, expected, 'ONLY_APPROVED_BINDING_MAY_CHANGE');
