function consumeFrames(buffer, record, start) {
  let i;
  while ((i = buffer.indexOf('\n')) >= 0) {
    const line = buffer.slice(0, i); buffer = buffer.slice(i + 1);
    if (!line.trim()) continue;
    const value = JSON.parse(line);
    assert.deepEqual(Object.keys(value).sort(), ['probeId', 'seq', 'serverElapsedMs']);
    record.frames.push({ ...value, clientElapsedMs: +(mono() - start).toFixed(3), clientMonotonicMs: mono() });
  }
  return buffer;
}
function assessStream(record) {
  assert.equal(record.status, 200);
  assert.match(record.headers['content-type'], /^application\/x-ndjson/);
  assert.equal(record.headers['cache-control'], 'no-store');
  assert.equal(record.headers['x-accel-buffering'], 'no');
  assert.deepEqual(record.frames.map(f => f.seq), [1, 2, 3]);
  const f = record.frames;
  assert.equal(new Set(f.map(x => x.probeId)).size, 1);
  record.clientGapsMs = [f[1].clientElapsedMs-f[0].clientElapsedMs, f[2].clientElapsedMs-f[1].clientElapsedMs];
  record.serverGapsMs = [f[1].serverElapsedMs-f[0].serverElapsedMs, f[2].serverElapsedMs-f[1].serverElapsedMs];
  record.firstFrameBeforeCompletionMs = record.completedMs-f[0].clientElapsedMs;
  // Diagnostic staged visibility, not a production latency SLA.
  record.visibilityPass = record.firstFrameBeforeCompletionMs > 100 && record.clientGapsMs.every(ms => ms > 50);
  record.compression = record.headers['content-encoding'] ?? 'UNCOMPRESSED / NOT NEGOTIATED';
  assert.ok(record.visibilityPass, 'BUFFERED_OR_NOT_STAGED');
}
async function fetchSample(base, path = 'stream', disconnect = false) {
  const start = mono(), controller = new AbortController();
  const record = { transport: base === local ? 'loopback' : 'tailscale', client: 'node-fetch-reader', path, frames: [] };
  const response = await fetch(base + prefix + path, { headers: disconnect ? { 'accept-encoding': 'identity' } : {}, redirect: 'error', signal: AbortSignal.any([controller.signal, AbortSignal.timeout(8000)]) });
  record.status = response.status; record.headers = safeHeaders(response.headers);
  const reader = response.body.getReader(), decoder = new TextDecoder(); let buffer = '';
  try {
    while (true) {
      const value = await reader.read();
      if (value.done) break;
      buffer = consumeFrames(buffer + decoder.decode(value.value, { stream: true }), record, start);
      if (disconnect && record.frames.length) {
        record.abortMonotonicMs = mono(); record.abortClientMs = mono() - start;
        controller.abort(); await reader.cancel().catch(() => {}); break;
      }
    }
