  assert.equal(code, 0, 'CURL_FAILED: ' + stderr.slice(0,200));
  return record;
}
async function streams(base) {
  for (const client of ['curl-identity', 'curl-compressed', 'node-fetch-reader']) {
    for (let i = 0; i < 5; i++) {
      const record = client === 'node-fetch-reader' ? await fetchSample(base) : await curlSample(base, client === 'curl-compressed');
      results.samples.push(record); save('transport-results', results);
      assessStream(record);
    }
    console.log(JSON.stringify({ phase: base === local ? 'loopback' : 'tailscale', client, samples: 5, status: 'PASS' }));
  }
}
async function disconnects(base) {
  const record = await fetchSample(base, 'disconnect', true);
  results.disconnects.push(record); assert.equal(record.status, 200); assert.equal(record.frames.length, 1);
  const id = record.frames[0].probeId;
  // Observe longer than both scheduled emissions; bounded by the 5s diagnostic window.
  await delay(700);
  let events = serverEvents.filter(x => x.probeId === id);
  for (let i = 0; i < 40 && !events.some(x => ['request.abort','stream.cancel'].includes(x.event)); i++) { await delay(100); events = serverEvents.filter(x => x.probeId === id); }
  record.serverEvents = events;
  const signal = events.find(x => ['request.abort','stream.cancel'].includes(x.event));
  record.signalLatencyMs = signal ? signal.serverMonotonicMs-record.abortMonotonicMs : null;
  record.afterFirstEmitCount = events.filter(x => x.event === 'emit' && x.seq > 1).length;
  record.pass = !!signal && record.signalLatencyMs <= 5000 && record.afterFirstEmitCount === 0 && events.some(x => x.event === 'timers.cleared');
  save('transport-results', results); assert.ok(record.pass, 'DISCONNECT_PROPAGATION_FAILED');
  const control = await fetchSample(base, 'disconnect'); results.samples.push(control); assessStream(control);
  record.normalControlProbeId = control.frames[0].probeId;
  console.log(JSON.stringify({ phase: record.transport, disconnect: 'PASS', signal: signal.event, signalLatencyMs: record.signalLatencyMs }));
}
async function origins(base) {
  const cases = [
    ['same-origin', { origin: base, 'sec-fetch-site': 'same-origin' }, 200],
    ['different-origin', { origin: 'https://probe-invalid.example' }, 403],
    ['cross-site', { origin: base, 'sec-fetch-site': 'cross-site' }, 403],
    ['missing-origin', {}, 403],
    ['null-origin', { origin: 'null' }, 403],
    ['forged-forwarded', { origin: 'https://probe-invalid.example', 'x-forwarded-host': 'probe-invalid.example', 'x-forwarded-proto': 'https' }, 403],
    ['same-origin-forged-forwarded', { origin: base, 'x-forwarded-host': 'probe-invalid.example', 'x-forwarded-proto': 'http' }, 200]
  ];
  for (const [name, headers, expectedStatus] of cases) {
    const response = await fetch(base + prefix + 'origin', { method: 'POST', body: '{}', headers: { 'content-type': 'application/json', ...headers }, redirect: 'error', signal: AbortSignal.timeout(8000) });
    const diagnostic = await response.json();
    const record = { transport: base === local ? 'loopback' : 'tailscale', name, expectedStatus, status: response.status, diagnostic, pass: response.status === expectedStatus };
    results.origins.push(record); save('transport-results', results);
    assert.deepEqual(Object.keys(diagnostic).sort(), ['scheme','host','forwardedProtoPresent','forwardedProto','expected','originMatch','status'].sort());
    if (!record.pass) { console.log(JSON.stringify({ phase: record.transport, origin: 'FAIL', case: name, diagnostic })); throw new Error('ORIGIN_GATE_FAILED:' + name); }
  }
  console.log(JSON.stringify({ phase: base === local ? 'loopback' : 'tailscale', origin: 'PASS' }));
}
async function portOpen() {
  return await new Promise(resolve => { const socket = net.connect({ host: '127.0.0.1', port: 43183 }); socket.once('connect', () => { socket.destroy(); resolve(true); }); socket.once('error', () => resolve(false)); });
}
async function cleanup() {
  if (closing) return; closing = true;
  const report = { startedAt: stamp(), bindingAttempted, ownedBindingCreated: owned };
  try {
    const current = status();
    if (owned && current.Web?.[hostname + ':9443']?.Handlers?.['/']?.Proxy === 'http://127.0.0.1:43183') {
      const r = spawnSync('/usr/bin/tailscale', ['serve','--https=9443','off'], { encoding: 'utf8', timeout: 10000 });
      report.removalExit = r.status; report.removedAt = stamp();
    } else if (current.TCP?.['9443']) report.cleanupConflict = 'NOT_OWNED_EXACT_TARGET; not removed';
    if (bindingStart) report.bindingDurationMs = +(mono()-bindingStart).toFixed(3);
    report.serveAfter = status(); report.configMatchesBefore = JSON.stringify(report.serveAfter) === JSON.stringify(before);
    report.ownedTemporaryBindingCount = report.serveAfter.TCP?.['9443'] ? 1 : 0;
  } catch (e) { report.error = e.message; }
