    await delay(300); report.probeListenerStopped = !await portOpen();
    const probe = spawnSync('/usr/bin/curl', ['--silent','--show-error','--noproxy','*','--connect-timeout','2','--max-time','3',remote + prefix + 'stream'], { env, encoding: 'utf8', timeout: 4000 });
