    report.finishedAt = stamp(); save('cleanup-result', report); save('server-events', serverEvents); save('transport-results', results);
    console.log(JSON.stringify({ cleanup: report.configMatchesBefore && report.probeListenerStopped && report.ownedTemporaryBindingCount === 0 ? 'PASS' : 'FAIL', bindingDurationMs: report.bindingDurationMs }));
  }
}
const overallTimer = setTimeout(() => { results.failure = 'WINDOW_TIMEOUT'; void cleanup().then(() => process.exit(1)); }, Math.max(1, Date.parse('2026-09-15T14:37:53+09:00') - Date.now() - 15000));
let bindingTimer;
try {
  assert.deepEqual(status(), before);
  assert.ok(!await portOpen(), 'PORT_43183_OCCUPIED');
  assert.equal(JSON.parse(readFileSync(work + '/node_modules/next/package.json')).version,'16.2.10');
  const prod = readFileSync('/home/yangzhen/projects/my-lms-system/src/features/teaching-agent/server/transport/student-handlers.ts','utf8');
  const probe = readFileSync(work + '/probe.mjs','utf8');
  const authority = "const url = new URL(request.url), expected = `${url.protocol}//${request.headers.get('host') ?? url.host}`;";
  const denial = "request.headers.get('origin') !== expected || request.headers.get('sec-fetch-site') === 'cross-site'";
  assert.ok(prod.includes(authority) && probe.includes(authority) && prod.includes(denial) && probe.includes(denial));
  save('probe-integrity', { nextVersion: '16.2.10', productionHandlerSha256: sha(prod), probeSha256: sha(probe), originExpressionsByteEqual: true, compressOverride: false, productConfigSha256: sha(readFileSync('/home/yangzhen/projects/my-lms-system/next.config.ts')), envVariableNames: Object.keys(env), isolatedDirectory: work });
  server = spawn(process.execPath, ['/home/yangzhen/projects/my-lms-system/node_modules/next/dist/bin/next','start','--hostname','127.0.0.1','--port','43183'], { cwd: work, env });
  results.serverPid = server.pid;
  let logBuffer = '';
  server.stdout.on('data', chunk => { logBuffer += chunk; let i; while ((i = logBuffer.indexOf('\n')) >= 0) { const line = logBuffer.slice(0,i); logBuffer = logBuffer.slice(i+1); if (line.startsWith('R4B_EVENT ')) serverEvents.push(JSON.parse(line.slice(10))); } });
  server.stderr.on('data', () => {});
  for (let i = 0; i < 100 && !await portOpen(); i++) await delay(100);
  assert.ok(await portOpen(), 'PROBE_START_FAILED');
  const listeners = spawnSync('/usr/bin/ss',['-lnt'],{encoding:'utf8'}).stdout.split('\n').filter(l=>/:43183\s/.test(l));
  assert.equal(listeners.length,1); assert.ok(listeners[0].includes('127.0.0.1:43183')); results.loopbackOnlyListener = true;
  await streams(local); await disconnects(local); await origins(local);
  results.loopback = 'PASS'; save('transport-results', results);
  assert.deepEqual(status(), before, 'BEFORE_BINDING_DRIFT');
  assert.ok(Date.now() < Date.parse('2026-09-15T14:37:53+09:00') - 120000, 'INSUFFICIENT_WINDOW');
